package app.zhijian.notes;
import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import android.content.Context;import android.graphics.Bitmap;import android.net.Uri;import org.junit.*;import org.junit.runner.RunWith;import static org.junit.Assert.*;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.Base64;
import app.zhijian.notes.data.PaperDb;import app.zhijian.notes.files.*;import app.zhijian.notes.backup.*;
@RunWith(AndroidJUnit4.class) public class MediaBackupTest{
 private String png(int color)throws Exception{Bitmap bitmap=Bitmap.createBitmap(6,4,Bitmap.Config.ARGB_8888);bitmap.eraseColor(color);ByteArrayOutputStream out=new ByteArrayOutputStream();bitmap.compress(Bitmap.CompressFormat.PNG,100,out);bitmap.recycle();return "data:image/png;base64,"+Base64.getEncoder().encodeToString(out.toByteArray());}
 @Test public void removedHistoricalPicturesAndFilesSurviveBackupAndRestore()throws Exception{Context context=InstrumentationRegistry.getInstrumentation().getTargetContext();AttachmentStore store=new AttachmentStore(context);File source=File.createTempFile("backup-pdf-",".pdf",context.getCacheDir());String id=null;try(PaperDb db=new PaperDb(context)){try{try(FileOutputStream out=new FileOutputStream(source)){out.write("%PDF-1.4\nfixture\n%%EOF".getBytes(StandardCharsets.UTF_8));}JSONObject first=store.saveImage(png(0xff886644)),second=store.saveImage(png(0xff448866)),file=new NoteFileStore(context,store).importFile(Uri.fromFile(source));JSONObject note=db.save("notes",new JSONObject().put("title","媒体备份恢复").put("mode","rich").put("content","<p><img src=\""+first.getString("src")+"\" width=\"50%\"></p>").put("attachments",new JSONArray().put(file)));id=note.getString("id");store.prune(db.snapshot(),null);db.save("notes",new JSONObject(note.toString()).put("content","<p><img src=\""+second.getString("src")+"\" width=\"75%\"></p>").put("attachments",new JSONArray()));store.prune(db.snapshot(),null);BackupService backup=new BackupService(context,db,store.directory);ByteArrayOutputStream bytes=new ByteArrayOutputStream();backup.write(bytes);assertTrue(backup.snapshot().getJSONObject("media").has(file.getString("src").substring(6)));db.execute("notes.trash",new JSONObject().put("id",id));db.execute("notes.delete",new JSONObject().put("id",id));store.prune(db.snapshot(),null);assertFalse(new File(context.getFilesDir(),file.getString("src")).exists());backup.restore(new ByteArrayInputStream(bytes.toByteArray()));JSONObject restored=db.get("notes",id);assertTrue(restored.getString("content").contains("width=\"75%\""));JSONObject version=restored.getJSONArray("_history").getJSONObject(0);assertTrue(version.getString("content").contains(first.getString("src")));assertEquals(file.getString("src"),version.getJSONArray("attachments").getJSONObject(0).getString("src"));assertTrue(new File(context.getFilesDir(),file.getString("src")).isFile());assertTrue(new File(context.getFilesDir(),first.getString("src")).isFile());int before=db.snapshot().getJSONArray("notes").length();backup.restore(new ByteArrayInputStream(bytes.toByteArray()));assertEquals(before,db.snapshot().getJSONArray("notes").length());}finally{if(id!=null){try{db.execute("notes.trash",new JSONObject().put("id",id));db.execute("notes.delete",new JSONObject().put("id",id));}catch(Exception ignored){}}source.delete();store.prune(db.snapshot(),null);}}}
}
